import React, { useState } from 'react';
import { Box } from '@metamask/design-system-react';
import {
  Icon,
  IconName,
  IconSize,
  PolymorphicRef,
  Popover,
  PopoverHeader,
  PopoverPosition,
  PopoverProps,
  Text,
} from '../../../components/component-library';
import {
  IconColor,
  JustifyContent,
  TextAlign,
  TextVariant,
} from '../../../helpers/constants/design-system';
import Column from './column';

const Tooltip = React.forwardRef(
  (
    {
      children,
      title,
      triggerElement,
      disabled = false,
      onClose,
      iconName,
      iconColor = IconColor.iconAlternative,
      style,
      ...props
    }: PopoverProps<'div'> & {
      triggerElement?: React.ReactElement;
      disabled?: boolean;
      onClose?: () => void;
      iconName?: IconName;
      iconColor?: IconColor;
    },
    ref?: PolymorphicRef<'div'>,
  ) => {
    const [isOpen, setIsOpen] = useState(false);
    const [referenceElement, setReferenceElement] =
      useState<HTMLSpanElement | null>(null);

    const handleMouseEnter = () => setIsOpen(true);
    const handleMouseLeave = () => setIsOpen(false);
    const setBoxRef = (newRef: HTMLSpanElement | null) =>
      setReferenceElement(newRef);

    return (
      <Box ref={ref}>
        <Box
          ref={setBoxRef}
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
          className="flex"
        >
          {triggerElement ??
            (iconName && (
              <Icon color={iconColor} name={iconName} size={IconSize.Sm} />
            )) ?? (
              <Icon name={IconName.Info} color={iconColor} size={IconSize.Sm} />
            )}
        </Box>
        {!disabled && (
          <Popover
            position={PopoverPosition.Auto}
            referenceElement={referenceElement}
            isOpen={isOpen}
            onClickOutside={handleMouseLeave}
            style={{
              maxWidth: '264px',
              paddingInline: '12px',
              paddingTop: '12px',
              paddingBottom: '12px',
              transitionTimingFunction: 'linear',
              display: 'inherit',
              ...style,
            }}
            preventOverflow
            flip
            hasArrow
            isPortal
            {...props}
          >
            <Column gap={2}>
              {title && (
                <PopoverHeader
                  textAlign={TextAlign.Center}
                  justifyContent={
                    onClose
                      ? JustifyContent.spaceBetween
                      : JustifyContent.center
                  }
                  onClose={onClose}
                  childrenWrapperProps={{ style: { whiteSpace: 'nowrap' } }}
                >
                  {title}
                </PopoverHeader>
              )}
              <Text
                justifyContent={JustifyContent.center}
                variant={TextVariant.bodySm}
              >
                {children}
              </Text>
            </Column>
          </Popover>
        )}
      </Box>
    );
  },
);

export default Tooltip;
